-- Default B-tree index:
CREATE INDEX idx_apprentices_name ON apprentices (name);

-- Composite index — leftmost prefix matters:
CREATE INDEX idx_completions_app_quest
  ON completions (apprentice_id, quest_id);

-- Now this is a fast index lookup, not a scan:
SELECT * FROM apprentices WHERE name = 'Eleanor';

-- This too — leftmost prefix on the composite:
SELECT * FROM completions WHERE apprentice_id = 1;

-- This DOES NOT use the composite index — quest_id alone is
-- not a prefix of (apprentice_id, quest_id):
SELECT * FROM completions WHERE quest_id = 2;

