-- Indexes:
-- idx_apprentices_name      ON apprentices (name)
-- idx_completions_app_quest ON completions (apprentice_id, quest_id)

-- Query A — uses idx_apprentices_name (equality lookup):
SELECT * FROM apprentices WHERE name = 'Eleanor';

-- Query B — uses idx_apprentices_name (prefix LIKE — sortable):
SELECT * FROM apprentices WHERE name LIKE 'El%';

-- Query C — does NOT use the index (suffix LIKE):
SELECT * FROM apprentices WHERE name LIKE '%nor';

-- Query D — uses idx_completions_app_quest (leftmost prefix on composite):
SELECT * FROM completions WHERE apprentice_id = 1;

-- Query E — DOES NOT use idx_completions_app_quest
-- (quest_id alone is not a prefix of (apprentice_id, quest_id)):
SELECT * FROM completions WHERE quest_id = 2;

-- Query F — does NOT use idx_apprentices_name
-- (function applied to the indexed column):
SELECT * FROM apprentices WHERE LOWER(name) = 'eleanor';
